INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6431600, 953936, 113156, '<td valign="top">One never tires of a pigeon photo, especially if its well done like this, the shadows are great.</td>', 'One never tires of a pigeon photo, especially if its well done like this, the shadows are great.', '2011-06-02 05:06:03.000000', NULL, 1),
(6431601, 954282, 113156, '<td valign="top">elegant and superb,</td>', 'elegant and superb,', '2011-06-02 05:07:11.000000', NULL, 1),
(6431602, 954791, 113156, '<td valign="top">posture is everything, it says it all.</td>', 'posture is everything, it says it all.', '2011-06-02 05:11:24.000000', NULL, 1),
(6431603, 954484, 113156, '<td valign="top">I bow to the king of the beach, such a happy scene and incredibly well processed.</td>', 'I bow to the king of the beach, such a happy scene and incredibly well processed.', '2011-06-02 05:17:18.000000', NULL, 1),
(6431605, 954617, 113156, '<td valign="top">Excellent perspective, should be somewhere at the top, well done.</td>', 'Excellent perspective, should be somewhere at the top, well done.', '2011-06-02 05:21:21.000000', NULL, 1),
(6431650, 954778, 18073, '<td valign="top">WOW!  I almost had sensory overload looking at this shot - there is just so much colour, I love it!<br/> <br/>Really like the composition too, one of my faves so far, cracking job</td>', 'WOW!  I almost had sensory overload looking at this shot - there is just so much colour, I love it! Really like the composition too, one of my faves so far, cracking job', '2011-06-02 07:42:11.000000', NULL, 1),
(6431654, 954781, 69487, '<td valign="top">I find some lines leading up to the tv that make me question a thing or two.  The shadow makes me think again.  If it was actually dropped and it has some motion blur to it, looks like it would have clipped the edge of the dumpster and made a nice mess.  I just had to comment because I found it interesting.</td>', 'I find some lines leading up to the tv that make me question a thing or two.  The shadow makes me think again.  If it was actually dropped and it has some motion blur to it, looks like it would have clipped the edge of the dumpster and made a nice mess.  I just had to comment because I found it interesting.', '2011-06-02 07:52:50.000000', NULL, 1),
(6431673, 954260, 58715, '<td valign="top">IMO this is DNMC. Not voting.</td>', 'IMO this is DNMC. Not voting.', '2011-06-02 09:01:20.000000', NULL, 1),
(6431684, 954005, 129807, '<td valign="top">.<br/><br/><i>Message edited by author 2011-06-20 10:49:39.</i></td>', '.', '2011-06-02 09:34:54.000000', '2011-06-20 11:49:39.000000', 1),
(6431863, 953936, 73942, '<td valign="top">loving the shadows and how the 3rd pigeon seems to be watching what''s going on</td>', 'loving the shadows and how the 3rd pigeon seems to be watching what''s going on', '2011-06-02 13:10:14.000000', NULL, 1),
(6431865, 954023, 73942, '<td valign="top">love your title</td>', 'love your title', '2011-06-02 13:11:39.000000', NULL, 1),
(6431917, 954775, 88897, '<td valign="top">absolutely beautiful</td>', 'absolutely beautiful', '2011-06-02 14:41:05.000000', NULL, 1),
(6431921, 954778, 87554, '<td valign="top">As a photograph, this is technically flawed in many ways, but despite that I love the concept and it has a great feel to it. Would have given a 10 if the focus wasn''t off and the subject were on the left third entering the scene instead of the right third leaving the scene. Depth of field could be quite a bit shallower too. I don''t need to see so much detail in the background, the focus should be on the girl.</td>', 'As a photograph, this is technically flawed in many ways, but despite that I love the concept and it has a great feel to it. Would have given a 10 if the focus wasn''t off and the subject were on the left third entering the scene instead of the right third leaving the scene. Depth of field could be quite a bit shallower too. I don''t need to see so much detail in the background, the focus should be on the girl.', '2011-06-02 14:50:22.000000', NULL, 1),
(6431925, 954747, 87554, '<td valign="top">If this isn''t an HDR, what processing steps did you take? There are white and black halos around some areas indicative of HDR processing, though the Clarity slider in PhotoShop''s Camera Raw can also cause this defect if you''re not careful.</td>', 'If this isn''t an HDR, what processing steps did you take? There are white and black halos around some areas indicative of HDR processing, though the Clarity slider in PhotoShop''s Camera Raw can also cause this defect if you''re not careful.', '2011-06-02 14:56:09.000000', NULL, 1),
(6431927, 954508, 87554, '<td valign="top">Nice idea, put more thought into your background next time.</td>', 'Nice idea, put more thought into your background next time.', '2011-06-02 14:57:19.000000', NULL, 1),
(6431928, 954617, 87554, '<td valign="top">Read the contest description again. Nice photo, but doesn''t meet the criteria for this challenge.</td>', 'Read the contest description again. Nice photo, but doesn''t meet the criteria for this challenge.', '2011-06-02 14:59:29.000000', NULL, 1),
(6431930, 954790, 87554, '<td valign="top">This would be great if it were properly focused.</td>', 'This would be great if it were properly focused.', '2011-06-02 15:01:03.000000', NULL, 1),
(6432011, 953936, 114225, '<td valign="top">I really like the way the shadows interact with the rest of the scene. But I''m not so sure how this is an <b>unusual</b> view of objects off the ground.</td>', 'I really like the way the shadows interact with the rest of the scene. But I''m not so sure how this is an unusual view of objects off the ground.', '2011-06-02 17:31:07.000000', NULL, 1),
(6432012, 954747, 114225, '<td valign="top">Very cool. Almost feels like these are making Chinese letters.</td>', 'Very cool. Almost feels like these are making Chinese letters.', '2011-06-02 17:32:21.000000', NULL, 1),
(6432015, 954682, 114225, '<td valign="top">Love the expression. I''m thinking this may be the best entry of the challenge.</td>', 'Love the expression. I''m thinking this may be the best entry of the challenge.', '2011-06-02 17:34:59.000000', NULL, 1),
(6432016, 954682, 108069, '<td valign="top">This is great<br/> <br/>Wow. That was all I could come up with? (No pun intended.) I must have been tired. I don''t have much more to say, but I love how natural he''s positioned, as though he''s chatting to a friend on the street. It''s cool to jump over trains as well. Great stuff.</td>', 'This is great Wow. That was all I could come up with? (No pun intended.) I must have been tired. I don''t have much more to say, but I love how natural he''s positioned, as though he''s chatting to a friend on the street. It''s cool to jump over trains as well. Great stuff.', '2011-06-02 17:35:04.000000', NULL, 1),
(6432038, 954441, 132996, '<td valign="top">Hilarious. :D</td>', 'Hilarious. :D', '2011-06-02 18:10:29.000000', NULL, 1),
(6432039, 954587, 132996, '<td valign="top">Wonderful composition! :)</td>', 'Wonderful composition! :)', '2011-06-02 18:11:23.000000', NULL, 1),
