(6434458, 953758, 121053, '<td valign="top">Nice colors, shadows, composition and focus.</td>', 'Nice colors, shadows, composition and focus.', '2011-06-05 11:31:28.000000', NULL, 1),
(6434461, 953788, 121053, '<td valign="top">Fog certainly fits the theme.  This could have used something else for more interest, like a boat or beach chair.</td>', 'Fog certainly fits the theme.  This could have used something else for more interest, like a boat or beach chair.', '2011-06-05 11:33:36.000000', NULL, 1),
(6434462, 954587, 121053, '<td valign="top">Beautiful shot.</td>', 'Beautiful shot.', '2011-06-05 11:33:58.000000', NULL, 1),
(6434464, 953739, 121053, '<td valign="top">I like your photo.  Having trouble equating "Lighter Than Air" with "In the air."  Maybe the challenge should be renamed since it seems to be a common problem.</td>', 'I like your photo.  Having trouble equating "Lighter Than Air" with "In the air."  Maybe the challenge should be renamed since it seems to be a common problem.', '2011-06-05 11:34:43.000000', NULL, 1),
(6434466, 954815, 121053, '<td valign="top">Still trying to figure out what I am seeing.</td>', 'Still trying to figure out what I am seeing.', '2011-06-05 11:35:27.000000', NULL, 1),
(6434470, 954765, 121053, '<td valign="top">Scary!</td>', 'Scary!', '2011-06-05 11:36:16.000000', NULL, 1),
(6434501, 954778, 31742, '<td valign="top">love it 10</td>', 'love it 10', '2011-06-05 11:57:41.000000', NULL, 1),
(6434507, 954782, 121053, '<td valign="top">I would like the balloon to be more in focus.  The balance and composition are good.</td>', 'I would like the balloon to be more in focus.  The balance and composition are good.', '2011-06-05 12:08:15.000000', NULL, 1),
(6434509, 954773, 121053, '<td valign="top">I like your photo, but not all of it is quite in focus.</td>', 'I like your photo, but not all of it is quite in focus.', '2011-06-05 12:18:36.000000', NULL, 1),
(6434510, 953950, 121053, '<td valign="top">Great title, great shot.</td>', 'Great title, great shot.', '2011-06-05 12:19:43.000000', NULL, 1),
(6434512, 954485, 121053, '<td valign="top">This must have taken HOURS to catch just like this.  But wait... the sun doesn''t take that long to rise.  Good job.</td>', 'This must have taken HOURS to catch just like this.  But wait... the sun doesn''t take that long to rise.  Good job.', '2011-06-05 12:20:24.000000', NULL, 1),
(6434519, 954041, 121053, '<td valign="top">Wow!</td>', 'Wow!', '2011-06-05 12:30:47.000000', NULL, 1),
(6434521, 953319, 121053, '<td valign="top">Wishing the whole person was inside the photo, but great catch! Wishing for sharper focus.</td>', 'Wishing the whole person was inside the photo, but great catch! Wishing for sharper focus.', '2011-06-05 12:35:55.000000', NULL, 1),
(6434587, 954072, 133848, '<td valign="top">As a mom of 3 kids that play soccer, I know how hard it is to get the perfect soccer shot. Nice job!</td>', 'As a mom of 3 kids that play soccer, I know how hard it is to get the perfect soccer shot. Nice job!', '2011-06-05 13:57:51.000000', NULL, 1),
(6434766, 953788, 101702, '<td valign="top">Not sure that this meets the challenge... maybe I''m too narrowminded?</td>', 'Not sure that this meets the challenge... maybe I''m too narrowminded?', '2011-06-05 18:05:35.000000', NULL, 1),
(6434776, 954010, 101702, '<td valign="top">Shame about the stray popcorn at the top left - kind of attracts the eye. May look better as a "portrait" crop rather than "landscape".</td>', 'Shame about the stray popcorn at the top left - kind of attracts the eye. May look better as a "portrait" crop rather than "landscape".', '2011-06-05 18:07:58.000000', NULL, 1),
(6434780, 953758, 101702, '<td valign="top">Great idea but I think the lighting is a bit harsh. The shadows on the marbles are fine but the shadow of the person looks a bit overwhelming.</td>', 'Great idea but I think the lighting is a bit harsh. The shadows on the marbles are fine but the shadow of the person looks a bit overwhelming.', '2011-06-05 18:10:06.000000', NULL, 1),
(6435375, 954041, 118154, '<td valign="top">Nice idea.</td>', 'Nice idea.', '2011-06-06 03:25:51.000000', NULL, 1),
(6435376, 954502, 118154, '<td valign="top">Like this shot.</td>', 'Like this shot.', '2011-06-06 03:26:18.000000', NULL, 1),
(6435409, 954260, 133799, '<td valign="top">It is horrible. Have you saw the subject of a challenge?</td>', 'It is horrible. Have you saw the subject of a challenge?', '2011-06-06 04:32:03.000000', NULL, 1),
(6435764, 954785, 61222, '<td valign="top">Noise takes away from this cool abstract of this.</td>', 'Noise takes away from this cool abstract of this.', '2011-06-06 11:29:21.000000', NULL, 1),
